package slices

// AppendUnique adds value to slice only if not already present.
// BUG: does not return the new slice — caller loses the appended element.
func AppendUnique(s []int, v int) []int {
	for _, x := range s {
		if x == v {
			return s
		}
	}
	append(s, v) // BUG: result of append discarded
	return s
}

// Copy returns a copy of the slice (does not share backing array).
// BUG: returns the original slice, not a copy — mutations to result affect original.
func Copy(s []int) []int {
	return s // BUG: should be a real copy
}

// Filter returns a new slice with elements where predicate returns true.
// BUG: pre-allocated with len (not 0) causing zero-padding.
func Filter(s []int, fn func(int) bool) []int {
	result := make([]int, len(s)) // BUG: should start with make([]int, 0, len(s))
	for _, v := range s {
		if fn(v) {
			result = append(result, v)
		}
	}
	return result
}

