package slices_test

import (
	"testing"

	"github.com/ai-verification/slice-bugs/slices"
)

func TestAppendUnique(t *testing.T) {
	s := []int{1, 2, 3}
	s = slices.AppendUnique(s, 4)
	if len(s) != 4 || s[3] != 4 {
		t.Fatalf("expected [1 2 3 4], got %v", s)
	}
}

func TestAppendUniqueNoDuplicate(t *testing.T) {
	s := []int{1, 2, 3}
	s = slices.AppendUnique(s, 2)
	if len(s) != 3 {
		t.Fatalf("expected length 3, got %d", len(s))
	}
}

func TestCopyIsIndependent(t *testing.T) {
	original := []int{1, 2, 3}
	copy := slices.Copy(original)
	copy[0] = 99
	if original[0] == 99 {
		t.Fatal("Copy shares backing array with original")
	}
}

func TestFilter(t *testing.T) {
	s := []int{1, 2, 3, 4, 5}
	even := slices.Filter(s, func(v int) bool { return v%2 == 0 })
	if len(even) != 2 || even[0] != 2 || even[1] != 4 {
		t.Fatalf("expected [2 4], got %v", even)
	}
}

func BenchmarkAppendUnique(b *testing.B) {
	for i := 0; i < b.N; i++ {
		s := make([]int, 0, 100)
		for j := 0; j < 100; j++ {
			s = slices.AppendUnique(s, j)
		}
	}
}
